const fullString = chunk0 + chunk1 + chunk2 + chunk3 + chunk4 + chunk5 + chunk6 + chunk7 + chunk8 + chunk9 + chunk10;

const rawData = fullString.split('^').map(line => {
    let part = line.split('|');
    return [parseInt(part[0]), part[1], part[2]];
});

let currentCategory = 'all';

function renderCategories() {
    const container = document.getElementById('categoryButtons');
    let html = `<button class="cat-btn active" onclick="filterByCategory('all', this)">Semua</button>`;
    categories.forEach((cat, index) => {
        html += `<button class="cat-btn" onclick="filterByCategory(${index}, this)">${cat}</button>`;
    });
    container.innerHTML = html;
}

function renderProducts(dataToRender) {
    const grid = document.getElementById('productGrid');
    if (dataToRender.length === 0) {
        grid.innerHTML = `<div class="no-result">Produk tidak ditemukan, bree!</div>`;
        return;
    }

    let html = '';
    dataToRender.forEach(item => {
        let catId = item[0];
        let name = item[1];
        let kemasan = item[2] ? `Kemasan: ${item[2]}` : 'Kemasan: -';
        let catName = categories[catId] || 'Lainnya';

        html += `
            <div class="product-card">
                <div>
                    <div class="product-category">${catName}</div>
                    <h3 class="product-name">${name}</h3>
                </div>
                <div>
                    <span class="product-kemasan">${kemasan}</span>
                </div>
            </div>
        `;
    });
    grid.innerHTML = html;
}

function filterByCategory(catId, btnElement) {
    currentCategory = catId;
    document.querySelectorAll('.cat-btn').forEach(btn => btn.classList.remove('active'));
    btnElement.classList.add('active');
    filterProducts();
}

function filterProducts() {
    const keyword = document.getElementById('searchInput').value.toLowerCase();
    
    const filtered = rawData.filter(item => {
        const matchCategory = (currentCategory === 'all' || item[0] === currentCategory);
        const matchKeyword = item[1].toLowerCase().includes(keyword) || (item[2] && item[2].toLowerCase().includes(keyword));
        return matchCategory && matchKeyword;
    });

    renderProducts(filtered);
}

renderCategories();
renderProducts(rawData);